import { useTranslation } from "../../i18n/LanguageContext";
import { useProjectConfigStore } from "../../stores/projectConfigStore";
import { X } from "lucide-react";

export function CopyFromGlobalModal(): JSX.Element | null {
  const { t } = useTranslation();
  const copyModalOpen = useProjectConfigStore((s) => s.copyModalOpen);
  const copyModalType = useProjectConfigStore((s) => s.copyModalType);
  const closeCopyModal = useProjectConfigStore((s) => s.closeCopyModal);

  if (!copyModalOpen || !copyModalType) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50">
      <div className="bg-background rounded-lg shadow-lg w-full max-w-lg mx-4 p-6">
        <div className="flex items-center justify-between mb-4">
          <h2 className="text-lg font-semibold">
            Copy from Global ({copyModalType})
          </h2>
          <button
            className="p-1 hover:bg-card rounded-md"
            onClick={closeCopyModal}
          >
            <X className="w-5 h-5" />
          </button>
        </div>
        <p className="text-muted-foreground">
          Copy from global modal - Coming soon
        </p>
      </div>
    </div>
  );
}

import { createContext, useContext, useState, useCallback, type ReactNode } from 'react'
import en from './locales/en.json'
import zhCN from './locales/zh-CN.json'

export type Locale = 'en' | 'zh-CN'

const translations: Record<Locale, Record<string, string>> = { en, 'zh-CN': zhCN }

interface LanguageContextValue {
  locale: Locale
  setLocale: (locale: Locale) => void
  t: (key: string, params?: Record<string, string | number>) => string
}

const LanguageContext = createContext<LanguageContextValue>(null!)

export function LanguageProvider({ children }: { children: ReactNode }): JSX.Element {
  const [locale, setLocaleState] = useState<Locale>(() => {
    const saved = localStorage.getItem('language') as Locale | null
    return saved === 'zh-CN' ? 'zh-CN' : 'en'
  })

  const setLocale = useCallback((l: Locale) => {
    setLocaleState(l)
    localStorage.setItem('language', l)
  }, [])

  const t = useCallback((key: string, params?: Record<string, string | number>): string => {
    let value = translations[locale]?.[key] ?? translations.en[key] ?? key
    if (params) {
      Object.entries(params).forEach(([k, v]) => {
        value = value.replace(new RegExp(`\\{\\{${k}\\}\\}`, 'g'), String(v))
      })
    }
    return value
  }, [locale])

  return (
    <LanguageContext.Provider value={{ locale, setLocale, t }}>
      {children}
    </LanguageContext.Provider>
  )
}

export function useTranslation(): LanguageContextValue {
  return useContext(LanguageContext)
}

