import { useNavigate } from "react-router-dom";
import { Trash2 } from "lucide-react";
import { useTranslation } from "../../i18n/LanguageContext";

export interface ProjectInfo {
  projectDir: string;
  projectName: string;
  agentCount: number;
  activeCount: number;
  lastActivity: string;
}

interface ProjectCardProps {
  project: ProjectInfo;
  onDelete: (projectDir: string) => void;
}

export function ProjectCard({ project, onDelete }: ProjectCardProps): JSX.Element {
  const { t } = useTranslation();
  const navigate = useNavigate();

  const formatTime = (dateStr: string): string => {
    const date = new Date(dateStr);
    const now = new Date();
    const diffMs = now.getTime() - date.getTime();
    const diffMins = Math.floor(diffMs / 60000);
    const diffHours = Math.floor(diffMins / 60);
    const diffDays = Math.floor(diffHours / 24);

    if (diffMins < 1) return t("office.justNow");
    if (diffMins < 60) return t("office.minutesAgo", { count: diffMins });
    if (diffHours < 24) return t("office.hoursAgo", { count: diffHours });
    return t("office.daysAgo", { count: diffDays });
  };

  const handleClick = (): void => {
    navigate(`/office/project/${encodeURIComponent(project.projectDir)}`);
  };

  const handleDelete = (e: React.MouseEvent): void => {
    e.stopPropagation();
    if (confirm(t("office.deleteConfirm", { name: project.projectName }))) {
      onDelete(project.projectDir);
    }
  };

  return (
    <div
      className="bg-card border border-border rounded-lg p-4 cursor-pointer hover:border-primary/50 transition-colors"
      onClick={handleClick}
    >
      <div className="flex items-start justify-between">
        <div className="flex-1 min-w-0">
          <h3 className="text-lg font-semibold text-foreground truncate">
            {project.projectName}
          </h3>
          <p className="text-sm text-muted-foreground truncate mt-1">
            {project.projectDir}
          </p>
        </div>
        <div className="flex items-center gap-2 ml-4">
          <button
            className="p-1.5 hover:bg-red-500/10 rounded-md text-muted-foreground hover:text-red-500"
            onClick={handleDelete}
            title={t("office.deleteAllSessions")}
          >
            <Trash2 className="w-4 h-4" />
          </button>
          {project.activeCount > 0 ? (
            <span className="flex items-center gap-1 text-sm text-green-500">
              <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse" />
              {project.activeCount}
            </span>
          ) : (
            <span className="flex items-center gap-1 text-sm text-muted-foreground">
              <span className="w-2 h-2 bg-muted-foreground/50 rounded-full" />
              {project.activeCount}
            </span>
          )}
        </div>
      </div>
      <div className="mt-4 flex items-center justify-between text-sm">
        <span className="text-muted-foreground">
          {project.agentCount === 1 ? t("office.sessions", { count: project.agentCount }) : t("office.sessionsPlural", { count: project.agentCount })}
        </span>
        <span className="text-muted-foreground">
          {formatTime(project.lastActivity)}
        </span>
      </div>
    </div>
  );
}

import { contextBridge, ipcRenderer } from "electron";
import { IPC } from "../shared/ipc-channels";
import type { Agent } from "../shared/types/agent";
import type { Skill } from "../shared/types/skill";
import type { InstalledPlugin } from "../shared/types/plugin";
import type { Command } from "../shared/types/command";
import type { Settings } from "../shared/types/settings";
import type {
  MarketplaceSource,
  MarketplacePlugin,
  MarketplacePluginDetail,
  InstalledPluginRecord,
} from "../shared/types/marketplace";
import type { HookDefinition } from "../shared/types/hook";
import type { MCPServer } from "../shared/types/mcp";
import type {
  ProjectAgent,
  ProjectSkill,
  ProjectMCPServer,
  ProjectCommand,
  ProjectHook,
  ProjectPlan,
  ProjectSummary,
  ProjectAgentFormData,
  ProjectSkillFormData,
  ProjectMCPFormData,
  ProjectCommandFormData,
  ProjectHookFormData,
} from "../shared/types/project-config";

// Types for plugin detail
interface PluginDetail {
  manifest: { name: string; version: string; description: string } | null;
  agents: Agent[];
  skills: Skill[];
  commands: Command[];
  hooks: Array<{
    pluginId: string;
    event: string;
    matcher: string;
    hooks: unknown[];
  }>;
}

// File tree node type
interface FileNode {
  name: string;
  path: string;
  isDirectory: boolean;
  children?: FileNode[];
}

const api = {
  agents: {
    list: (): Promise<Agent[]> => ipcRenderer.invoke(IPC.AGENTS_LIST),
    read: (name: string): Promise<Agent | null> =>
      ipcRenderer.invoke(IPC.AGENTS_READ, name),
    write: (
      name: string,
      data: {
        name: string;
        description: string;
        tools: string[];
        model: string;
        body: string;
      },
    ): Promise<void> => ipcRenderer.invoke(IPC.AGENTS_WRITE, name, data),
    delete: (name: string): Promise<void> =>
      ipcRenderer.invoke(IPC.AGENTS_DELETE, name),
  },
  skills: {
    list: (): Promise<{ personal: Skill[]; plugin: Skill[] }> =>
      ipcRenderer.invoke(IPC.SKILLS_LIST),
    read: (source: string, name: string): Promise<Skill | null> =>
      ipcRenderer.invoke(IPC.SKILLS_READ, source, name),
    write: (
      name: string,
      body: string,
      metadata: Record<string, unknown>,
    ): Promise<void> =>
      ipcRenderer.invoke(IPC.SKILLS_WRITE, name, body, metadata),
    delete: (name: string): Promise<void> =>
      ipcRenderer.invoke(IPC.SKILLS_DELETE, name),
    getDirectoryTree: (): Promise<{
      personal: FileNode[];
      plugin: FileNode[];
    }> => ipcRenderer.invoke(IPC.SKILLS_DIRECTORY_TREE),
    readFile: (filePath: string): Promise<string | null> =>
      ipcRenderer.invoke(IPC.SKILLS_READ_FILE, filePath),
    writeFile: (filePath: string, content: string): Promise<void> =>
      ipcRenderer.invoke(IPC.SKILLS_WRITE_FILE, filePath, content),
  },
  plugins: {
    list: (): Promise<InstalledPlugin[]> =>
      ipcRenderer.invoke(IPC.PLUGINS_LIST),
    enable: (id: string): Promise<void> =>
      ipcRenderer.invoke(IPC.PLUGINS_ENABLE, id),
    disable: (id: string): Promise<void> =>
      ipcRenderer.invoke(IPC.PLUGINS_DISABLE, id),
    detail: (id: string): Promise<PluginDetail | null> =>
      ipcRenderer.invoke(IPC.PLUGINS_DETAIL, id),
    uninstall: (id: string): Promise<void> =>
      ipcRenderer.invoke(IPC.PLUGINS_UNINSTALL, id),
  },
  commands: {
    list: (): Promise<Command[]> => ipcRenderer.invoke(IPC.COMMANDS_LIST),
    read: (pluginId: string, name: string): Promise<Command | null> =>
      ipcRenderer.invoke(IPC.COMMANDS_READ, pluginId, name),
  },
  settings: {
    read: (): Promise<Settings> => ipcRenderer.invoke(IPC.SETTINGS_READ),
    write: (settings: Settings): Promise<void> =>
      ipcRenderer.invoke(IPC.SETTINGS_WRITE, settings),
  },
  marketplace: {
    list: (): Promise<MarketplaceSource[]> =>
      ipcRenderer.invoke(IPC.MARKETPLACE_LIST),
    add: (repoUrl: string): Promise<MarketplaceSource> =>
      ipcRenderer.invoke(IPC.MARKETPLACE_ADD, repoUrl),
    remove: (id: string): Promise<void> =>
      ipcRenderer.invoke(IPC.MARKETPLACE_REMOVE, id),
    browse: (marketplaceId: string): Promise<MarketplacePlugin[]> =>
      ipcRenderer.invoke(IPC.MARKETPLACE_BROWSE, marketplaceId),
    pluginDetail: (
      marketplaceId: string,
      pluginName: string,
    ): Promise<MarketplacePluginDetail | null> =>
      ipcRenderer.invoke(
        IPC.MARKETPLACE_PLUGIN_DETAIL,
        marketplaceId,
        pluginName,
      ),
    refresh: (id: string): Promise<void> =>
      ipcRenderer.invoke(IPC.MARKETPLACE_REFRESH, id),
    install: (
      marketplaceId: string,
      pluginName: string,
    ): Promise<InstalledPluginRecord> =>
      ipcRenderer.invoke(IPC.MARKETPLACE_INSTALL, marketplaceId, pluginName),
    getInstalled: (): Promise<InstalledPluginRecord[]> =>
      ipcRenderer.invoke(IPC.MARKETPLACE_GET_INSTALLED),
  },
  hooks: {
    list: (): Promise<HookDefinition[]> => ipcRenderer.invoke(IPC.HOOKS_LIST),
  },
  mcp: {
    list: (): Promise<MCPServer[]> => ipcRenderer.invoke(IPC.MCP_LIST),
    templates: (): Promise<unknown[]> => ipcRenderer.invoke(IPC.MCP_TEMPLATES),
    activate: (template: unknown, env: Record<string, string>): Promise<void> =>
      ipcRenderer.invoke(IPC.MCP_ACTIVATE, template, env),
    deactivate: (name: string): Promise<void> =>
      ipcRenderer.invoke(IPC.MCP_DEACTIVATE, name),
    update: (name: string, config: Partial<MCPServer>): Promise<void> =>
      ipcRenderer.invoke(IPC.MCP_UPDATE, name, config),
  },
  onFileChanged: (
    callback: (event: { type: string; path: string }) => void,
  ) => {
    const handler = (
      _event: Electron.IpcRendererEvent,
      data: { type: string; path: string },
    ): void => {
      callback(data);
    };
    ipcRenderer.on(IPC.FS_CHANGED, handler);
    return () => ipcRenderer.removeListener(IPC.FS_CHANGED, handler);
  },
  cli: {
    run: (
      command: string[],
    ): Promise<{
      success: boolean;
      stdout: string;
      stderr: string;
      exitCode: number | null;
    }> => ipcRenderer.invoke(IPC.CLI_RUN, command),
    runAgent: (
      agentName: string,
      prompt: string,
    ): Promise<{ success: boolean; error?: string }> =>
      ipcRenderer.invoke(IPC.CLI_RUN_AGENT, agentName, prompt),
    testSkill: (
      skillName: string,
      prompt: string,
    ): Promise<{ success: boolean; error?: string }> =>
      ipcRenderer.invoke(IPC.CLI_TEST_SKILL, skillName, prompt),
    kill: (): Promise<{ success: boolean }> => ipcRenderer.invoke(IPC.CLI_KILL),
    onOutput: (
      callback: (data: {
        type: "stdout" | "stderr" | "close";
        data?: string;
        code?: number | null;
      }) => void,
    ) => {
      const handler = (
        _event: Electron.IpcRendererEvent,
        data: {
          type: "stdout" | "stderr" | "close";
          data?: string;
          code?: number | null;
        },
      ): void => {
        callback(data);
      };
      ipcRenderer.on(IPC.CLI_OUTPUT, handler);
      return () => ipcRenderer.removeListener(IPC.CLI_OUTPUT, handler);
    },
  },
  office: {
    getProjects: (): Promise<Array<{
      projectDir: string;
      projectName: string;
      agentCount: number;
      activeCount: number;
      lastActivity: string;
    }>> => ipcRenderer.invoke(IPC.OFFICE_GET_PROJECTS),

    getProjectAgents: (projectDir: string): Promise<Array<{
      id: number;
      sessionId: string;
      projectDir: string;
      isActive: boolean;
    }>> => ipcRenderer.invoke(IPC.OFFICE_GET_PROJECT_AGENTS, projectDir),

    joinTerminal: (projectDir: string, sessionId?: string): Promise<{ success: boolean }> =>
      ipcRenderer.invoke(IPC.OFFICE_JOIN_TERMINAL, projectDir, sessionId),

    getAgentContext: (projectDir: string, sessionId: string): Promise<unknown> =>
      ipcRenderer.invoke(IPC.OFFICE_GET_AGENT_CONTEXT, projectDir, sessionId),

    deleteAgent: (projectDir: string, sessionId: string): Promise<{ success: boolean; error?: string }> =>
      ipcRenderer.invoke(IPC.OFFICE_DELETE_AGENT, projectDir, sessionId),

    deleteAgents: (projectDir: string, sessionIds: string[]): Promise<{ success: boolean; deletedCount: number; errors: string[] }> =>
      ipcRenderer.invoke(IPC.OFFICE_DELETE_AGENTS, projectDir, sessionIds),

    deleteProject: (projectDir: string): Promise<{ success: boolean; error?: string; deletedCount?: number }> =>
      ipcRenderer.invoke(IPC.OFFICE_DELETE_PROJECT, projectDir),
  },
  plans: {
    list: (): Promise<Array<{
      fileName: string;
      filePath: string;
      name: string;
      createdAt: string;
      modifiedAt: string;
      size: number;
      preview: string;
    }>> => ipcRenderer.invoke(IPC.PLANS_LIST),

    read: (fileName: string): Promise<string | null> =>
      ipcRenderer.invoke(IPC.PLANS_READ, fileName),

    write: (fileName: string, content: string): Promise<{ success: boolean; error?: string }> =>
      ipcRenderer.invoke(IPC.PLANS_WRITE, fileName, content),

    delete: (fileName: string): Promise<{ success: boolean; error?: string }> =>
      ipcRenderer.invoke(IPC.PLANS_DELETE, fileName),

    batchDelete: (fileNames: string[]): Promise<{ success: boolean; deletedCount: number; errors: string[] }> =>
      ipcRenderer.invoke(IPC.PLANS_BATCH_DELETE, fileNames),
  },
  projectConfig: {
    // Agents
    listAgents: (projectDir: string): Promise<ProjectAgent[]> =>
      ipcRenderer.invoke(IPC.PROJECT_CONFIG_AGENTS_LIST, projectDir),
    readAgent: (projectDir: string, name: string): Promise<ProjectAgent | null> =>
      ipcRenderer.invoke(IPC.PROJECT_CONFIG_AGENTS_READ, projectDir, name),
    writeAgent: (projectDir: string, name: string, data: ProjectAgentFormData): Promise<void> =>
      ipcRenderer.invoke(IPC.PROJECT_CONFIG_AGENTS_WRITE, projectDir, name, data),
    deleteAgent: (projectDir: string, name: string): Promise<void> =>
      ipcRenderer.invoke(IPC.PROJECT_CONFIG_AGENTS_DELETE, projectDir, name),

    // Skills
    listSkills: (projectDir: string): Promise<ProjectSkill[]> =>
      ipcRenderer.invoke(IPC.PROJECT_CONFIG_SKILLS_LIST, projectDir),
    readSkill: (projectDir: string, name: string): Promise<ProjectSkill | null> =>
      ipcRenderer.invoke(IPC.PROJECT_CONFIG_SKILLS_READ, projectDir, name),
    writeSkill: (projectDir: string, name: string, data: ProjectSkillFormData): Promise<void> =>
      ipcRenderer.invoke(IPC.PROJECT_CONFIG_SKILLS_WRITE, projectDir, name, data),
    deleteSkill: (projectDir: string, name: string): Promise<void> =>
      ipcRenderer.invoke(IPC.PROJECT_CONFIG_SKILLS_DELETE, projectDir, name),

    // MCP
    listMCPServers: (projectDir: string): Promise<ProjectMCPServer[]> =>
      ipcRenderer.invoke(IPC.PROJECT_CONFIG_MCP_LIST, projectDir),
    writeMCPServer: (projectDir: string, name: string, data: ProjectMCPFormData): Promise<void> =>
      ipcRenderer.invoke(IPC.PROJECT_CONFIG_MCP_WRITE, projectDir, name, data),
    deleteMCPServer: (projectDir: string, name: string): Promise<void> =>
      ipcRenderer.invoke(IPC.PROJECT_CONFIG_MCP_DELETE, projectDir, name),

    // Plans
    listPlans: (projectDir: string): Promise<ProjectPlan[]> =>
      ipcRenderer.invoke(IPC.PROJECT_CONFIG_PLANS_LIST, projectDir),
    readPlan: (projectDir: string, name: string): Promise<ProjectPlan | null> =>
      ipcRenderer.invoke(IPC.PROJECT_CONFIG_PLANS_READ, projectDir, name),
    writePlan: (projectDir: string, name: string, content: string): Promise<void> =>
      ipcRenderer.invoke(IPC.PROJECT_CONFIG_PLANS_WRITE, projectDir, name, content),
