      ipcRenderer.invoke(IPC.PROJECT_CONFIG_PLANS_DELETE, projectDir, name),

    // Hooks
    listHooks: (projectDir: string): Promise<ProjectHook[]> =>
      ipcRenderer.invoke(IPC.PROJECT_CONFIG_HOOKS_LIST, projectDir),
